var progress = new Progress<int>(p => status.Text = p + "%");
var report = await BuildReportAsync(progress);   // start now, resume on completion
status.Text = "done: " + report.Pages + " pages"; // runs on the captured context

var w = new BackgroundWorker { WorkerReportsProgress = true,
                               WorkerSupportsCancellation = true };
w.DoWork += (s, e) => e.Result = BuildReport();
w.ProgressChanged += (s, e) => status.Text = e.ProgressPercentage + "%";
w.RunWorkerCompleted += (s, e) =>                   // exactly once
{
    if (e.Cancelled) status.Text = "cancelled";
    else if (e.Error != null) status.Text = e.Error.Message;
    else status.Text = "done";
};
w.RunWorkerAsync();                                 // start now, returns void
